import {connections,worldPoint,tileOf,placementError,uid} from './core.mjs';
export function defaults(p){p.variables??=[];p.enemyGroups??=[];p.resourceRules??=[];p.objectiveGroups??=[{id:'main',name:'메인',kind:'main'}];p.successMode??='extraction';return p;}
export function checkFeatures(p){defaults(p);for(const key of ['variables','enemyGroups','resourceRules','objectiveGroups']){if(!Array.isArray(p[key])||p[key].length>300||new Set(p[key].map(x=>x.id)).size!==p[key].length)throw Error(key+': 중복 ID 또는 목록 크기를 확인하세요.');for(const x of p[key])if(!x.id||typeof x.name!=='string'||!x.name.trim()||x.name.length>160)throw Error('이름과 ID를 확인하세요.');}
 if(p.objectiveGroups.filter(g=>g.kind==='main').length!==1)throw Error('메인 목표 묶음은 하나여야 합니다.');for(const o of p.objectives||[]){if(o.groupId){const group=p.objectiveGroups.find(g=>g.id===o.groupId);if(!group)throw Error('목표 묶음이 없습니다.');o.required=group.kind==='main';}if(o.amount!==undefined&&(!Number.isInteger(o.amount)||o.amount<1||o.amount>3600)||o.enabled!==undefined&&typeof o.enabled!=='boolean')throw Error('목표 수량·활성 상태를 확인하세요.');}
 const names=p.objectiveGroups.filter(x=>x.kind==='sub').map(x=>x.name.trim());if(new Set(names).size!==names.length)throw Error('서브 목표 묶음 이름은 서로 달라야 합니다.');
 if(!['extraction','direct'].includes(p.successMode))throw Error('목표 완료 결과를 확인하세요.');
 for(const v of p.variables)if(!Number.isFinite(v.initial)||Math.abs(v.initial)>1e9)throw Error('변수 초기값을 확인하세요.');
 for(const g of p.enemyGroups)if(!['tile','room'].includes(g.scope)||!(g.scope==='tile'?p.placements:p.rooms).some(x=>x.id===g.targetId)||!Number.isInteger(g.count)||g.count<1||g.count>64||!Number.isInteger(g.waves)||g.waves<0||g.waves>1000||!Number.isFinite(g.interval)||g.interval<1||g.interval>3600||!Number.isFinite(g.minDistance)||g.minDistance<0||g.minDistance>128)throw Error('적 수량·반복·간격·거리를 확인하세요.');
 for(const r of p.resourceRules)if(!['tile','room'].includes(r.scope)||!(r.scope==='tile'?p.placements:p.rooms).some(x=>x.id===r.targetId)||!['ammo','health','cargo','keycard','object'].includes(r.kind)||!['ammo','health'].includes(r.kind)&&r.total!==r.bundles||!Number.isInteger(r.total)||r.total<1||r.total>5000||!Number.isInteger(r.bundles)||r.bundles<1||r.bundles>1000||r.bundles>r.total)throw Error('보급 총 사용량과 묶음 수를 확인하세요.');
 return p;
}
export function hasExit(p){return p.gimmicks.some(g=>g.type==='extraction')||p.successMode==='direct'&&p.objectives.some(g=>g.required);}
export function checks(p){const net=connections(p);return [{title:'연결되지 않은 문 없음',done:net.ports.every(x=>net.connected.has(x.key))},{title:'시작지점 존재',done:p.gimmicks.some(g=>g.type==='spawn')},{title:'탈출 방법 존재',done:hasExit(p)}];}
export function setRole(p,id,role,on){const q=p.placements.find(x=>x.id===id),t=tileOf(p,q);if(!q||!t)return;const type=role==='entry'?'spawn':'extraction';p.gimmicks=p.gimmicks.filter(g=>!(g.type===type&&g.placementId===id));if(on)p.gimmicks.push({id:uid('device'),name:type==='spawn'?'진입점':'탈출 스캔',type,placementId:id,position:{x:Math.floor(t.size.x/2),y:1,z:Math.floor(t.size.z/2)},settings:type==='spawn'?{}:{duration:5,radius:2.5,requiredPlayers:'all',unlockOnObjectives:true}});}
/** Snap translations only to compatible doors. Coordinates remain in editor view units. */
export function magnetic(p,candidate,limit=.4){let best=null,distance=limit;const t=tileOf(p,candidate);if(!t)return candidate;const net=connections(p);for(const port of t.ports){const at=worldPoint(port,t,candidate);for(const other of net.ports){if(other.placementId===candidate.id||other.width!==port.width||other.height!==port.height||other.doorSettings?.type!==port.doorSettings?.type||Math.abs(other.y-at.y)>.001||({north:'south',south:'north',east:'west',west:'east'})[portFacing(port,candidate.rotation)]!==other.facing)continue;const dx=(other.x-at.x)/16,dz=(other.z-at.z)/16,d=Math.hypot(dx,dz);if(d<distance){const q={...candidate,x:Math.round((candidate.x+dx)*16)/16,z:Math.round((candidate.z+dz)*16)/16};if(!placementError(p,q)){best=q;distance=d;}}}}return best||candidate;}
function portFacing(port,angle){return ['north','east','south','west'][(['north','east','south','west'].indexOf(port.facing)+angle/90)%4];}
export function doses(total,bundles){if(!Number.isInteger(total)||!Number.isInteger(bundles)||bundles<1||total<bundles)throw Error('총 사용량과 묶음 수를 확인하세요.');return Array.from({length:bundles},(_,i)=>{let n=Math.floor(total/bundles)+(i<total%bundles?1:0),out=[];while(n>0){const dose=Math.min(5,n);out.push(dose);n-=dose;}return out;});}

export function needsV3(p){return (p.variables?.length||p.enemyGroups?.length||p.resourceRules?.length||p.objectiveGroups?.some(g=>g.kind==='sub')||p.successMode==='direct'||p.gimmicks.filter(g=>g.type==='spawn').length>1||p.gimmicks.some(g=>g.type==='object'||g.settings.containerSize&&g.settings.containerSize!=='legacy')||p.objectives.some(o=>['interact','survive','clear'].includes(o.type)||o.enabled===false||o.amount>1)||(p.programs||[]).some(rule=>JSON.stringify(rule).match(/when.progress|flow.until|do.enemies|do.music|do.alarm|"roomId":"tile:|valueVariable|"action":"activate"|"action":"deactivate"/)))?true:false;}

/** Capacity-only dry run. Actual random selection is made once by the server at mission preparation. */
export function resourcePlan(p){const slots=p.placements.flatMap(q=>(tileOf(p,q)?.asset?.slots||[]).map(s=>({...s,placementId:q.id,roomId:q.roomId,free:s.capacity||1,used:false}))),allocations=[];
 for(const r of [...(p.resourceRules||[])].sort((a,b)=>(a.scope==='tile'?0:1)-(b.scope==='tile'?0:1))){const object=!['ammo','health'].includes(r.kind);for(const bundle of doses(r.total,r.bundles)){const needed=object?1:bundle.length;const candidates=slots.filter(s=>s.kind===(object?'object':'container')&&(!object||!s.used)&&s.free>=needed&&(r.scope==='tile'?s.placementId===r.targetId:s.roomId===r.targetId)).sort((a,b)=>Number(a.used)-Number(b.used)||a.free-b.free);if(!candidates.length)throw Error(r.name+': 빈 슬롯 또는 수납 용량이 부족합니다.');const slot=candidates[0];slot.free-=needed;slot.used=true;allocations.push({ruleId:r.id,placementId:slot.placementId,slotId:slot.id,doses:bundle});}}
 return {slots,allocations};}
